 assignSheet:p=>{const t=s.staff.find(t=>t.id===p.id);openSheet(t.name+'の配置',Object.entries(D.roles).map(([key,d])=>{const temp=E.clone(s);temp.staff.find(x=>x.id===p.id).assigned=key;return '<div class="card"><div class="row spread"><h3>'+d.name+'</h3><span class="tag">主能力 '+(t.stats[d.stat]+(t.level-1)*2)+'</span></div><p class="small muted">'+d.desc+'</p><p class="edit-hint">倉庫 '+E.capacity(s)+'→'+E.capacity(temp)+' / 生産バッチ '+E.produceBatch(s)+'→'+E.produceBatch(temp)+' / 加工バッチ '+E.batch(s)+'→'+E.batch(temp)+'<br>研究 '+E.power(s,'lab')+'→'+E.power(temp,'lab')+' / 営業 '+E.power(s,'sales')+'→'+E.power(temp,'sales')+' / 職人 '+E.power(s,'workshop')+'→'+E.power(temp,'workshop')+'</p>'+btn(t.assigned===key?'今日の担当':t.usedDay===s.day?'明日の担当に予約':'今日から配置','do',{type:'assign',p:{id:p.id,role:key}},'btn secondary full mt',t.assigned===key&&!t.nextAssignment)+'</div>'}).join('')+'<p class="edit-hint">物流の容量が減っても在庫は捨てません。既存在庫の期限はどの配置でも変わりません。使用済みのスタッフは当日固定です。</p>')},
 trainingSheet:p=>{const t=s.staff.find(t=>t.id===p.id);openSheet(t.name+'の成長',btn('研修 '+yen(300+t.level*120)+' / 経験＋8','do',{type:'train',p},'btn full')+'<h3 class="mt">専門研修（Lv3〜）</h3><p class="small muted">初回20P、選び直し600円。担当に合う条件で効果を発揮します。</p>'+Object.entries({harvest:'農家：生産バッチ＋1',batch:'職人：加工バッチ＋2',finish:'職人：丁寧製造の品質を改善',bread:'職人：パン類の品質を改善',fresh:'物流：新規入庫の期限＋1日',study:'研究：日次研究P＋4',small:'営業：仕入れを1個単位に',local:'営業：町内の契約報酬＋5%'}).map(([key,label])=>btn(label+(t.spec===key?' ✓':''),'do',{type:'specialize',p:{id:p.id,spec:key}},'btn secondary full mt',t.level<3||t.spec===key)).join(''))},
 staffHistory:p=>{const t=s.staff.find(t=>t.id===p.id);openSheet(t.name+'の仕事ノート','<div class="center">'+Art.avatar(t)+'</div><p class="small">得意な商品：'+Object.entries(t.products).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([id,n])=>esc(E.item(s,id)?.name||id)+' '+n+'経験').join(' / ')+'</p>'+t.history.map(h=>'<p class="small mt">'+h.day+'日目 / '+esc(h.text)+'</p>').join(''))},
 wholesaleSheet:p=>openSheet('定番卸売の設定','<div class="sheet-product">'+food(p.id)+'<div><h3>'+esc(E.item(s,p.id).name)+'</h3><p class="small">1個 '+yen(E.item(s,p.id).price*.42)+'</p></div></div><div class="field-row"><label for="wholesale-n">1日の販売上限（0で停止）</label><input id="wholesale-n" type="number" min="0" max="99" value="'+(s.wholesale[p.id]||0)+'"></div>'+btn('設定を保存','wholesaleSave',p,'btn full')),wholesaleSave:(p,seq)=>{const target=Number($('wholesale-n').value);apply('wholesale',{id:p.id,target},seq)},
