 autoSheet:p=>{const a=s.auto[p.id];openSheet(D.auto[p.id].name+'の稼働条件','<label class="row"><input id="auto-enabled" type="checkbox" '+(a.enabled?'checked':'')+'> 稼働を許可</label><div class="field-row"><label for="auto-target">目標在庫</label><input id="auto-target" type="number" min="0" max="999" value="'+a.target+'"></div><details><summary>詳細な停止条件</summary><div class="field-row"><label for="auto-budget">1日予算（直接費）</label><input id="auto-budget" type="number" min="0" max="100000" value="'+a.budget+'"></div><div class="field-row"><label for="auto-quality">保証できない場合は停止</label><select id="auto-quality">'+D.ranks.map((r,i)=>'<option value="'+i+'" '+(a.minQuality===i?'selected':'')+'>'+r+'以上</option>').join('')+'</select></div><p class="small muted">予約品・ロック済み素材は使いません。レア素材への自動置き換えも行いません。</p></details>'+btn('稼働計画を保存','autoSave',p,'btn full mt'))},autoSave:(p,seq)=>{const cfg={id:p.id,target:Number($('auto-target').value),budget:Number($('auto-budget').value),minQuality:Number($('auto-quality').value),enabled:$('auto-enabled').checked};apply('autoConfig',cfg,seq)},
 prototypeSheet:()=>{try{const p=readDraft(),r=E.recipeDraft(s,p),plan=E.craftPlan(s,'draft',1,{recipe:r,policy:'trial'});if(!plan.ok){toast(plan.reason);return}openSheet('最初の一皿を試作','<h3>'+esc(p.name)+'</h3>'+tags(r.tags)+'<div class="preview-stats"><div><small>材料原価込み</small><b>'+yen(plan.totalCost)+'</b></div><div><small>品質帯</small><b>'+D.ranks[plan.q.floor]+'〜'+D.ranks[plan.q.cap]+'</b></div><div><small>加工枠</small><b>1枠</b></div></div>'+affinityHTML(r.affinity)+qualityOdds(plan.q)+'<p class="small muted">完成品1個と製法知識を得ます。素材は配合分を実際に消費します。失敗抽選による材料消失はありません。</p>'+btn('この配合で試作する','prototypeExecute',{draft:p},'btn full mt'))}catch(e){toast(e.message)}},prototypeExecute:(p,seq)=>{apply('prototype',p.draft,seq)},
