 recipeHistory:p=>{const r=s.recipes.find(r=>r.id===p.id);openSheet(r.name+'の歩み',affinityHTML(r.affinity)+(r.lastTasting?.sub?'<div class="notice mt">前回の試食：'+esc(r.lastTasting.sub)+'</div>':'')+'<p class="small">第'+r.recipeVersion+'版 / 代表スタッフ：'+esc(r.representative)+' / 販売 '+r.sales+'個</p>'+r.history.map(h=>'<p class="small mt">'+h.day+'日目 '+esc(h.text)+'</p>').join('')+r.reactions.slice(-5).map(h=>'<div class="notice mt">'+esc(h.customer)+'「'+esc(h.text)+'」</div>').join('')+r.awards.map(h=>'<p class="small mt">'+h.day+'日目 '+esc(h.contest)+' '+h.grade+'</p>').join(''))},
 contestPrepare:(p,seq)=>{if(apply('contestPrepare',p,seq))handlers.contestSheet(p)},contestSheet:p=>{const c=D.contests[p.key],lots=s.lots.filter(l=>!l.locked&&!l.reservation&&l.expiresAfterDay>=s.day&&(c.original?E.item(s,l.itemId).original&&E.item(s,l.itemId).formal:c.product?l.itemId===c.product:E.item(s,l.itemId).kind==='food'&&E.item(s,l.itemId).recipe));openSheet(c.name+'へ出品','<p class="small muted">提出すると商品1個を消費します。取消でも戻りません。出品料 '+yen(c.fee)+'（差し替え時の追加出品料なし）。</p>'+(lots.length?lots.map(l=>{const score=E.contestScore(s,p.key,l);return '<div class="card mt"><div class="row">'+food(l.itemId)+'<div class="grow"><h3>'+esc(E.item(s,l.itemId).name)+' '+rank(l.qualityRank)+'</h3><p class="small muted">予測 '+Math.round(score.base)+'点 / ±2点</p></div></div><p class="edit-hint">品質＋'+score.qualityScore+' / お題＋'+score.fit+' / 熟練＋'+Math.round(score.craftsmanship)+' / 開発＋'+score.original+'</p>'+btn('この1個を提出する','do',{type:'contest',p:{key:p.key,lot:l.lotId}},'btn secondary full mt')+'</div>'}).join(''):'<div class="empty mt">対象となる、予約・保護されていない在庫がありません。</div>'+contestPreparationCard(p.key)))},
 contestResult:p=>{const h=s.contestHistory[p.index];if(!h)return;const sc=h.entry.score;openSheet(D.contests[h.key]?.name||'旧大会'+'・'+h.grade,'<div class="hero-result">'+icon('trophy')+'<h2>'+h.grade+' / '+h.score+'点</h2><p>'+esc(h.entry.name)+' '+D.ranks[h.entry.lot.qualityRank]+'</p></div><div class="metric-grid"><div class="metric"><small>報酬</small><b>'+yen(h.money)+'</b></div><div class="metric"><small>評判</small><b>＋'+(h.score>=55?6:1)+'</b></div><div class="metric"><small>研究</small><b>＋'+(h.score>=55?25:10)+'P</b></div></div><p class="small mt">品質＋'+sc.qualityScore+' / お題適合＋'+sc.fit+' / 熟練＋'+Math.round(sc.craftsmanship)+' / 開発＋'+sc.original+'</p><div class="notice mt">次の改善候補：'+(sc.fit<20?'お題に合う特徴を持つ商品へ。':h.entry.lot.qualityRank<4?'素材を育て、品質研究と保証で仕上がりを安定させよう。':'この商品の製造熟練をさらに積み重ねよう。')+'</div>'+btn('歩みに残して、次へ','close',{},'btn full mt'));Audio.effect('award');celebrate()},
 rivalSheet:p=>{const r=D.rivals[p.key],lots=s.lots.filter(l=>!l.locked&&!l.reservation&&E.item(s,l.itemId).kind==='food');openSheet(r.name+'との料理対決','<p class="small">挑戦費 '+yen(r.fee)+' と食品1個を使用。敗北時は報酬なし。再戦は勝利後14日・敗北後3日。</p>'+(lots.length?lots.map(l=>{const v=E.rivalPreview(s,p.key,l);return '<div class="card mt"><div class="row">'+food(l.itemId)+'<div class="grow"><h3>'+esc(E.item(s,l.itemId).name)+' '+rank(l.qualityRank)+'</h3><p class="small">勝率 '+(v.chance*100).toFixed(1)+'%</p></div></div><p class="edit-hint">準備点 '+v.score.toFixed(1)+' / 相手基準 '+r.threshold+' / お題加点 '+v.fit+'</p>'+btn('この商品で挑む','do',{type:'rival',p:{key:p.key,lot:l.lotId}},'btn secondary full mt')+'</div>'}).join(''):'<div class="empty mt">挑戦用の食品を製造してください。</div>'))},
