 deliveryGuide:()=>deliveryGuide(),tutorialWork:()=>tutorialWork(),tutorialPreset:(p,seq)=>{apply('workPreset',{mode:'orders'},seq)},storyChoose:(p,seq)=>{const c=E.storyInvitation(s);if(apply('storyChoice',p,seq)){const f=E.focusLinks[s.progress.focus];openSheet(s.lastResult.title,'<p class="small">'+esc(s.lastResult.text)+'</p>'+btn(p.choice==='offer'?'候補の注文と必要な準備を見る':esc(f.label),p.choice==='offer'?'go':f.action,p.choice==='offer'?{to:'trade/orders'}:f.p,'btn full mt'));}},dayPreview:()=>{const a=advice();if(!a.close.ok){toast(a.close.reason);return}openSheet(s.day+'日目の営業を終えますか？',(s.progress.tutorial.enabled&&s.progress.tutorial.step<4?'<div class="notice mt">まだ最初の納品の途中です。続けるなら、案内の「'+esc(E.coach(s).label)+'」へ戻れます。納品前に日を進めることもできます。</div>'+btn('案内に戻る','go',{to:'home'},'btn secondary full mt'):'')+riskPanel()+cashBanner()+todayPanel()+closingSummary()+'<p class="edit-hint">候補の見送りや余った作業枠に罰則はありません。続けたい工夫があれば戻れます。</p><div class="sheet-footer"><div>'+btn('もう少し営業する','close',{},'btn secondary full')+'</div><div>'+btn(a.close.scheduledIds.length?'任せて今日を締める':'今日を締める','endDay',{day:s.day},'btn full')+'</div></div>',{type:'day'})},
 endDay:(p,seq)=>{if(apply('nextDay',p,seq)){if(s.ended)showEvaluation();else if(s.settings.fullReport||s.lastReport.failed.length||s.lastReport.contests.length)reportSheet(s.lastReport);else{go('home');Audio.effect('morning');toast(s.lastReport.day+'日目の営業完了 / 納品 '+s.lastReport.deliveries+'件・'+(s.lastReport.deliveredUnits||0)+'個 / 売上 '+yen(s.lastReport.sales)+'。詳しくはホームの日次報告へ。')}}},report:p=>reportSheet(s.reports[p.index]),evaluation:()=>showEvaluation(),reevaluation:p=>showEvaluation(p.index),continueRun:(p,seq)=>{apply('continue',{},seq)},
 settingsSave:()=>{Audio.unlock();if(apply('settings',{bgm:Number($('bgm').value),sfx:Number($('sfx').value),reduced:$('reduced').checked,short:$('short').checked,fullReport:$('full-report').checked}))toast(saved?'音と演出の設定を保存しました':'設定を反映しましたが、保存はできていません。')},
