 restoreSheet:()=>openSheet('直前の正常保存へ戻しますか？','<p class="small">直前の保存状態に戻ります。現在の進行を残す場合は、先にバックアップを書き出してください。壊れた主セーブは正常保存で置き換えます。</p><div class="sheet-footer">'+btn('書き出す','export',{},'btn secondary',!env)+btn('復元する','restoreExecute',{},'btn')+'</div>'),restoreExecute:()=>{try{env=store.restore();s=env.runs[env.current];blocked='';saved=true;closeSheet();render();toast('直前の正常保存を復元しました')}catch(e){toast(e.message)}},
