 newCompany:()=>openSheet('もうひとつの会社を始める','<p class="small muted">今の会社を残して、別のセーブで始めます。同じシードとルール版なら同じ初期条件になります。</p><div class="welcome-fields mt"><label>会社名<input id="new-name" maxlength="24" value="こもれび食品"></label><label>初期シード<input id="new-seed" maxlength="60" value="'+esc(s?.seed||welcomeSeed)+'"></label><label>シナリオ<select id="new-scenario">'+Object.entries(D.scenarios).map(([id,d])=>'<option value="'+id+'">'+d.name+'</option>').join('')+'</select></label></div><div id="scenario-hint" class="notice mt">'+D.scenarios.standard.desc+'</div>'+btn('この条件で開業する','startNew',{},'btn full mt')),
